class Solution {
public:
    std::vector<long long> minCost(int n, std::vector<std::vector<int>>& roads, std::vector<int>& appleCost, int k) {
        std::vector<std::vector<std::pair<int, int>>> graph(n + 1);
        for (const auto& r : roads) {
            graph[r[0]].push_back({r[1], r[2]});
            graph[r[1]].push_back({r[0], r[2]});
        }
        std::vector<long long> dist(n + 1, 1e16);
        std::priority_queue<std::pair<long long, int>, std::vector<std::pair<long long, int>>, std::greater<std::pair<long long, int>>> pq;
        for (int i = 1; i <= n; ++i) {
            dist[i] = appleCost[i - 1];
            pq.push({appleCost[i - 1], i});
        }
        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (d > dist[u]) continue;
            for (const auto& [v, w] : graph[u]) {
                long long new_cost = d + (long long)(k + 1) * w;
                if (new_cost < dist[v]) {
                    dist[v] = new_cost;
                    pq.push({new_cost, v});
                }
            }
        }
        std::vector<long long> ans(dist.begin() + 1, dist.end());
        return ans;
    }
};

class Solution {
    public long[] minCost(int n, int[][] roads, int[] appleCost, int k) {
        java.util.List<int[]>[] graph = new java.util.ArrayList[n + 1];
        for (int i = 0; i <= n; i++) graph[i] = new java.util.ArrayList<>();
        for (int[] r : roads) {
            graph[r[0]].add(new int[]{r[1], r[2]});
            graph[r[1]].add(new int[]{r[0], r[2]});
        }
        long[] dist = new long[n + 1];
        java.util.Arrays.fill(dist, Long.MAX_VALUE);
        java.util.PriorityQueue<long[]> pq = new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        for (int i = 1; i <= n; i++) {
            dist[i] = appleCost[i - 1];
            pq.offer(new long[]{appleCost[i - 1], i});
        }
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0];
            int u = (int) cur[1];
            if (d > dist[u]) continue;
            for (int[] edge : graph[u]) {
                int v = edge[0];
                int w = edge[1];
                long newCost = d + (long) (k + 1) * w;
                if (newCost < dist[v]) {
                    dist[v] = newCost;
                    pq.offer(new long[]{newCost, v});
                }
            }
        }
        long[] ans = new long[n];
        for (int i = 1; i <= n; i++) ans[i - 1] = dist[i];
        return ans;
    }
}

var minCost = function(n, roads, appleCost, k) {
    class MinHeap {
        constructor() { this.heap = []; }
        push(item) { this.heap.push(item); this._bubbleUp(this.heap.length - 1); }
        pop() {
            if (this.heap.length === 0) return null;
            const top = this.heap[0];
            const bottom = this.heap.pop();
            if (this.heap.length > 0) { this.heap[0] = bottom; this._bubbleDown(0); }
            return top;
        }
        size() { return this.heap.length; }
        _bubbleUp(i) {
            while (i > 0) {
                const p = Math.floor((i - 1) / 2);
                if (this.heap[i].d < this.heap[p].d) {
                    [this.heap[i], this.heap[p]] = [this.heap[p], this.heap[i]];
                    i = p;
                } else break;
            }
        }
        _bubbleDown(i) {
            const len = this.heap.length;
            while (true) {
                let s = i;
                const l = 2 * i + 1, r = 2 * i + 2;
                if (l < len && this.heap[l].d < this.heap[s].d) s = l;
                if (r < len && this.heap[r].d < this.heap[s].d) s = r;
                if (s !== i) {
                    [this.heap[i], this.heap[s]] = [this.heap[s], this.heap[i]];
                    i = s;
                } else break;
            }
        }
    }
    const graph = Array.from({ length: n + 1 }, () => []);
    for (const [u, v, w] of roads) {
        graph[u].push([v, w]);
        graph[v].push([u, w]);
    }
    const dist = new Array(n + 1).fill(Infinity);
    const pq = new MinHeap();
    for (let i = 1; i <= n; i++) {
        dist[i] = appleCost[i - 1];
        pq.push({ d: appleCost[i - 1], u: i });
    }
    while (pq.size() > 0) {
        const { d, u } = pq.pop();
        if (d > dist[u]) continue;
        for (const [v, w] of graph[u]) {
            const newCost = d + (k + 1) * w;
            if (newCost < dist[v]) {
                dist[v] = newCost;
                pq.push({ d: newCost, u: v });
            }
        }
    }
    return dist.slice(1);
};
